<?php
defined('ABSPATH')||exit; class CFP_Automation_Actions{public function run(array $actions,array $ctx,int $automation_id):void{foreach($actions as $a){$type=sanitize_key($a['type']??''); if('send_email'===$type){(new CFP_Email_Engine())->send_template((int)($a['email_id']??0),$ctx);} if('trigger_webhook'===$type){(new CFP_Webhooks())->send((int)($a['webhook_id']??0),$ctx);}} global $wpdb; $wpdb->insert(CFP_Database::table('automation_logs'),array('status'=>'success','event_type'=>$ctx['event']??'manual','meta'=>wp_json_encode(array('automation_id'=>$automation_id)),'created_at'=>current_time('mysql')));}}
